const config = $('Watch Configuration').first().json;
const rawBody = $json.body ?? $json.data ?? $json;
const body = typeof rawBody === 'string' ? rawBody : JSON.stringify(rawBody);
const statusCode = Number($json.statusCode ?? 200);

const UNKNOWN = 'UNKNOWN';
const BLOCKED = 'BLOCKED';
const ACTIONABLE = new Set(['IN_STOCK', 'PREORDER']);

function normalize(raw) {
  if (!raw) return UNKNOWN;
  const text = String(raw)
    .trim()
    .toLowerCase()
    .split('/')
    .pop()
    .replace(/[-_\s]/g, '');

  if (text.includes('preorder') || text.includes('presale')) return 'PREORDER';
  if (text.includes('backorder')) return 'BACKORDER';
  if (text.includes('outofstock') || text.includes('soldout') || text.includes('unavailable') || text.includes('discontinued')) return 'OUT_OF_STOCK';
  if (text.includes('limitedavailability') || text.includes('madetoorder') || text.includes('instock') || text.includes('instoreonly') || text.includes('onlineonly')) return 'IN_STOCK';
  return UNKNOWN;
}

let current = UNKNOWN;
if (statusCode === 401 || statusCode === 403 || statusCode === 429 || statusCode >= 500) {
  current = BLOCKED;
} else {
  const matches = [...body.matchAll(/"availability"\s*:\s*(?:"([^"]+)"|\[\s*"([^"]+)")/gi)]
    .map(m => m[1] || m[2])
    .filter(Boolean);

  const statuses = matches.map(normalize);
  const priority = { PREORDER: 50, IN_STOCK: 40, BACKORDER: 30, OUT_OF_STOCK: 20, UNKNOWN: 10 };
  current = statuses.sort((a, b) => (priority[b] || 0) - (priority[a] || 0))[0] || UNKNOWN;
}

const state = $getWorkflowStaticData('global');
state.statuses ??= {};
const key = config.label || config.url;
const previous = state.statuses[key] ?? null;

let baseline = false;
let changed = false;
let shouldAlert = false;

if (current !== UNKNOWN && current !== BLOCKED) {
  if (previous === null) {
    state.statuses[key] = current;
    baseline = true;
  } else if (previous !== current) {
    changed = true;
    shouldAlert = ACTIONABLE.has(current);
    state.statuses[key] = current;
  }
}

const title = shouldAlert ? `${current === 'PREORDER' ? 'PREORDER' : 'IN STOCK'}: ${config.productName}` : `Restock Watch: ${config.productName}`;
const message = shouldAlert
  ? `${config.productName} changed at ${config.label}: ${previous} -> ${current}\n${config.url}`
  : `${config.productName}: ${current}${baseline ? ' (baseline)' : changed ? ` (was ${previous})` : ''}`;

return [{
  json: {
    ...config,
    previous,
    current,
    baseline,
    changed,
    shouldAlert,
    title,
    message,
    checkedAt: new Date().toISOString()
  }
}];
